#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
vec2 pmod(vec2 p, float n) {
	float
	a=atan(p.x,p.y)+3.14159/n,
	b=6.28318/n;
	a=floor(a/b)*b;
	return rot(-a)*p;
}
vec3 smin(vec3 a, vec3 b, float k) {
	vec3 h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
vec3 kifs(vec3 p) {
	for (int i=0; i<3; i++) {
		p.yz*=rot(T);
		p.xz*=rot(T);
		p=smin(p,-p,-1.);
		p-=vec3(.26,.02,.1);
	}
	return p;
}
float ftor(vec3 p, vec2 s) {
	vec2 c=vec2(length(p.yz)-s.x,abs(p.x));
	c=abs(c)-s.y;
	return length(max(c,.0))+min(.0,max(c.x,c.y));
}
float tor(vec3 p, vec2 s) {
	vec2 c=vec2(length(p.xz)-s.x,p.y);
	return length(c)-s.y;
}
float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float glow=.0;
float map(vec3 p) {
	vec3 q=p,st=p;
	float seg=sign(round(p.y));
	p.xz=pmod(p.xz,6.);
	float t=T*3., n=1., off=2.5, pid=round(p.y/n), k=rnd(pid+12.);
	p.y-=clamp(pid,-1.,1.)*n;
	p.y-=sin(k+2.*sin(k*T*(k*5.)))*.01;
	st.y-=clamp(round(st.y/n),-1.,1.)*n;
	st.y*=1.+sin((T+seg*5.)*(1.+seg*.2)*22.+(22.)*atan(st.x,st.z))*.1;
	float d=ftor(p-vec3(125e-6*(cos(p.y*120.)-sin(p.z*120.)),0,off),vec2(.25-sin(1.5707+80.*p.x)*.0025,.125)+.025)-.025,
	band=tor(st,vec2(off,.1));
	glow+=.05/(.05+band*band*80.);

	d=min(d,band);
	q=kifs(q-vec3(0,.2,0));
	d=min(d,length(q)-1.);

	return d;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
void cam(inout vec3 p) {
	p.yz*=rot(-move.y*6.3/MN-.39+sin(T*.2));
	p.xz*=rot(-move.x*6.3/MN+T*.2);
}
void main(void) {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,exp(1.)-exp(-cos(T*.5))*1.5-10.),
	rd=N(vec3(uv,1.9));
	cam(p); cam(rd);
	const float steps=400., maxd=10.;
	float bnz=.0, a=1.;
	for (float i=.0; i<steps; i++) {
		float d=map(p);
		if (abs(d)<1e-3) {
			if (bnz++>1.) break;
			vec3 n=norm(p), l=N(vec3(dot(rd.xz,rd.xz))), r=reflect(rd,n);
			float fres=clamp(1.+dot(r,n),.0,1.);
			a*=mix(5e-3,.65,fres);
			rd=r;
			d=3e-2;
		}
		if (d>maxd) break;
		p+=rd*d;
	}
	col+=mix(vec3(0),a*vec3(.1,.4,.8),pow(dot(rd.xz,rd.xz),8.));
	col+=vec3(.95,.3,.8)*glow*.75;
	O=vec4(col,1);
}

